import { motion } from "framer-motion";

const galleryImages = [
  {
    url: "https://images.unsplash.com/photo-1558611848-73f7eb4001a1",
    title: "Strength Training",
  },
  {
    url: "https://images.unsplash.com/photo-1571019613454-1cb2f99b2d8b",
    title: "Gym Workout",
  },
  {
    url: "https://images.unsplash.com/photo-1517836357463-d25dfeac3438",
    title: "Weight Lifting",
  },
  {
    url: "https://images.unsplash.com/photo-1599058917212-d750089bc07e",
    title: "Personal Training",
  },
  {
    url: "https://images.unsplash.com/photo-1605296867304-46d5465a13f1",
    title: "Functional Fitness",
  },
  {
    url: "https://images.unsplash.com/photo-1546483875-ad9014c88eba",
    title: "Cardio Session",
  },
];

export default function Gallery() {
  return (
    <section
      id="gallery"
      className="bg-black py-32 px-6 scroll-mt-24"
    >
      <div className="max-w-7xl mx-auto">

        {/* HEADING */}
        <motion.div
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
          className="text-center mb-20"
        >
          <h2 className="text-4xl md:text-5xl font-bold">
            Training <span className="text-[#e9b21a]">Gallery</span>
          </h2>
          <p className="mt-6 text-gray-400 max-w-2xl mx-auto">
            A glimpse into our training culture, equipment, and workout
            environment at Bodyzeal Fitworks.
          </p>
        </motion.div>

        {/* GALLERY GRID */}
        <div className="grid sm:grid-cols-2 md:grid-cols-3 gap-8">
          {galleryImages.map((img, i) => (
            <motion.div
              key={i}
              initial={{ opacity: 0, scale: 0.9 }}
              whileInView={{ opacity: 1, scale: 1 }}
              viewport={{ once: true }}
              transition={{ duration: 0.5, delay: i * 0.1 }}
              className="group relative overflow-hidden rounded-2xl border border-white/10"
            >
              {/* IMAGE */}
              <img
                src={img.url}
                alt={img.title}
                className="w-full h-72 object-cover group-hover:scale-110 transition duration-700"
              />

              {/* OVERLAY */}
              <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition flex flex-col justify-end p-6">
                <h3 className="text-lg font-semibold text-white">
                  {img.title}
                </h3>

                {/* DOWNLOAD */}
                <a
                  href={img.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="mt-3 inline-block w-fit px-5 py-2 text-sm rounded-full bg-[#e9b21a] text-black font-semibold hover:bg-yellow-400 transition"
                >
                  Download Image
                </a>
              </div>
            </motion.div>
          ))}
        </div>

      </div>
    </section>
  );
}
